#!/usr/bin/env python3
"""Build one executor-ready Luau entrypoint from the two source modules."""
from pathlib import Path
import argparse
import sys

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / "dist" / "lesbhub-exporter.lua"


def bundle():
    engine = (ROOT / "src" / "engine.lua").read_text(encoding="utf-8").rstrip()
    ui = (ROOT / "src" / "ui.lua").read_text(encoding="utf-8").rstrip()
    return (
        "-- AUTO-GENERATED by scripts/build.py; edit src/engine.lua or src/ui.lua instead.\n"
        "-- Lesbhub Exporter V1 - public, read-only Roblox client inspection.\n\n"
        "local function loadEngine()\n" + engine + "\nend\n\n"
        "local function loadUI()\n" + ui + "\nend\n\n"
        "local Engine = loadEngine()\n"
        "local UI = loadUI()\n"
        "local environment = (type(getgenv) == 'function' and getgenv()) or _G\n"
        "environment.LesbhubExporterEngine = Engine\n"
        "local ok, err = pcall(UI.open, Engine)\n"
        "if not ok then\n"
        "    warn('[Lesbhub Exporter] WindUI unavailable: ' .. tostring(err))\n"
        "    warn('[Lesbhub Exporter] Engine is still available as LesbhubExporterEngine.capture(config, onProgress, control)')\n"
        "end\n"
    )


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="verify that the bundle is in sync")
    args = parser.parse_args()
    expected = bundle()
    if args.check:
        actual = DEST.read_text(encoding="utf-8") if DEST.exists() else ""
        if actual != expected:
            print("dist bundle out of date; run python scripts/build.py", file=sys.stderr)
            return 1
        print("Bundle is in sync.")
        return 0
    DEST.parent.mkdir(parents=True, exist_ok=True)
    DEST.write_text(expected, encoding="utf-8", newline="\n")
    print(f"Wrote {DEST} ({len(expected.encode('utf-8')):,} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
